using MyHealth.Domain.Abstractions;
using MyHealth.Domain.Training.Plans;
using MyHealth.Domain.Users;

namespace MyHealth.Domain.Training.Workouts;

public enum WorkoutStatus
{
    InProgress = 1,
    Paused = 2,
    Completed = 3,
    Abandoned = 4,
}

/// <summary>
/// One execution of a planned session. The id is generated by the phone so every call can be retried safely.
/// Only <see cref="WorkoutStatus.Completed"/> sessions count towards attendance; previewing a workout creates nothing.
/// </summary>
public sealed class WorkoutSession : AggregateRoot<Guid>
{
    /// <summary>How far in the future a device clock may be before a timestamp is rejected.</summary>
    public static readonly TimeSpan ClockSkewTolerance = TimeSpan.FromMinutes(5);

    private readonly List<SetLog> _sets = [];
    private readonly List<WorkoutPause> _pauses = [];

    private WorkoutSession(Guid id) : base(id) { }

    private WorkoutSession() { }

    public Guid ClientId { get; private set; }

    public Guid TrainingPlanId { get; private set; }

    public Guid PlanVersionId { get; private set; }

    public int PlanVersionNumber { get; private set; }

    public Guid PlannedSessionId { get; private set; }

    public string PlannedSessionName { get; private set; } = null!;

    public SessionKind Kind { get; private set; }

    public Guid TrainerProfileId { get; private set; }

    public Guid TrainerUserId { get; private set; }

    public WorkoutStatus Status { get; private set; }

    public DateTimeOffset StartedAt { get; private set; }

    public DateTimeOffset? CompletedAt { get; private set; }

    public DateTimeOffset? AbandonedAt { get; private set; }

    public string TimeZoneId { get; private set; } = null!;

    /// <summary>The client's local calendar date on completion; this is the attendance date.</summary>
    public DateOnly? LocalDate { get; private set; }

    public List<Guid> AllowedExerciseIds { get; private set; } = [];

    public WorkoutFeedback? Feedback { get; private set; }

    public FeedbackReply? Reply { get; private set; }

    /// <summary>The HKWorkout the phone saved for this session, if the client opted in (HK-06).</summary>
    public ExternalWorkoutExport? AppleHealthWorkout { get; private set; }

    public IReadOnlyCollection<SetLog> Sets => _sets.AsReadOnly();

    public IReadOnlyCollection<WorkoutPause> Pauses => _pauses.AsReadOnly();

    public DateTimeOffset? EndedAt => CompletedAt ?? AbandonedAt;

    public bool IsOpen => Status is WorkoutStatus.InProgress or WorkoutStatus.Paused;

    public static Result<WorkoutSession> Start(
        Guid id, Guid clientId, TrainingPlanVersion version, Guid plannedSessionId,
        DateTimeOffset startedAt, string timeZoneId, DateTimeOffset now)
    {
        if (id == Guid.Empty)
        {
            return WorkoutErrors.InvalidId;
        }

        if (version.ClientId != clientId)
        {
            return PlanErrors.NotFound;
        }

        var planned = version.Content.FindSession(plannedSessionId);
        if (planned is null)
        {
            return WorkoutErrors.PlannedSessionNotFound;
        }

        if (startedAt > now + ClockSkewTolerance)
        {
            return WorkoutErrors.FutureTimestamp;
        }

        if (!TimeZones.IsValid(timeZoneId))
        {
            return UserErrors.InvalidTimeZone;
        }

        var session = new WorkoutSession(id)
        {
            ClientId = clientId,
            TrainingPlanId = version.TrainingPlanId,
            PlanVersionId = version.Id,
            PlanVersionNumber = version.VersionNumber,
            PlannedSessionId = planned.Id,
            PlannedSessionName = planned.Name,
            Kind = planned.Kind,
            TrainerProfileId = version.TrainerProfileId,
            TrainerUserId = version.TrainerUserId,
            Status = WorkoutStatus.InProgress,
            StartedAt = startedAt,
            TimeZoneId = timeZoneId,
            AllowedExerciseIds = planned.AllowedExerciseIds().ToList(),
        };

        return session;
    }

    /// <summary>True when a retried start call describes this same session.</summary>
    public bool IsSameStart(Guid clientId, Guid trainingPlanId, Guid plannedSessionId) =>
        ClientId == clientId && TrainingPlanId == trainingPlanId && PlannedSessionId == plannedSessionId;

    public Result Pause(DateTimeOffset at)
    {
        if (Status == WorkoutStatus.Paused)
        {
            return Result.Success();
        }

        if (Status != WorkoutStatus.InProgress)
        {
            return WorkoutErrors.NotInProgress;
        }

        if (at < StartedAt)
        {
            return WorkoutErrors.BeforeStart;
        }

        _pauses.Add(new WorkoutPause(at));
        Status = WorkoutStatus.Paused;
        return Result.Success();
    }

    public Result Resume(DateTimeOffset at)
    {
        if (Status == WorkoutStatus.InProgress)
        {
            return Result.Success();
        }

        if (Status != WorkoutStatus.Paused)
        {
            return WorkoutErrors.NotPaused;
        }

        var pause = _pauses.Last(p => p.ResumedAt is null);
        if (at < pause.PausedAt)
        {
            return WorkoutErrors.BeforeStart;
        }

        pause.Close(at);
        Status = WorkoutStatus.InProgress;
        return Result.Success();
    }

    public Result Abandon(DateTimeOffset at)
    {
        if (Status == WorkoutStatus.Abandoned)
        {
            return Result.Success();
        }

        if (!IsOpen)
        {
            return WorkoutErrors.AlreadyFinished;
        }

        CloseOpenPause(at);
        Status = WorkoutStatus.Abandoned;
        AbandonedAt = at < StartedAt ? StartedAt : at;
        return Result.Success();
    }

    /// <summary>Records or corrects a set. The set id comes from the phone, so retries do not duplicate it.</summary>
    public Result LogSet(SetLogEntry entry, DateTimeOffset now)
    {
        if (!IsOpen)
        {
            return WorkoutErrors.AlreadyFinished;
        }

        if (entry.Repetitions is null && entry.DurationSeconds is null && entry.DistanceMeters is null)
        {
            return WorkoutErrors.EmptySet;
        }

        if (Kind == SessionKind.Strength && !AllowedExerciseIds.Contains(entry.ExerciseId))
        {
            return WorkoutErrors.ExerciseNotInSession;
        }

        if (entry.LoggedAt > now + ClockSkewTolerance)
        {
            return WorkoutErrors.FutureTimestamp;
        }

        var existing = _sets.Find(s => s.Id == entry.Id);
        if (existing is null)
        {
            _sets.Add(new SetLog(entry));
        }
        else
        {
            existing.Correct(entry);
        }

        return Result.Success();
    }

    public Result Complete(WorkoutFeedback feedback, DateTimeOffset completedAt, DateTimeOffset now)
    {
        // A retried completion must not fail nor change what was recorded.
        if (Status == WorkoutStatus.Completed)
        {
            return Result.Success();
        }

        if (Status == WorkoutStatus.Abandoned)
        {
            return WorkoutErrors.AlreadyFinished;
        }

        if (completedAt < StartedAt)
        {
            return WorkoutErrors.BeforeStart;
        }

        if (completedAt > now + ClockSkewTolerance)
        {
            return WorkoutErrors.FutureTimestamp;
        }

        var validFeedback = feedback.Validate();
        if (validFeedback.IsFailure)
        {
            return validFeedback;
        }

        CloseOpenPause(completedAt);
        Status = WorkoutStatus.Completed;
        CompletedAt = completedAt;
        LocalDate = TimeZones.LocalDate(completedAt, TimeZoneId);
        Feedback = feedback;

        Raise(new WorkoutCompleted(Id, ClientId, TrainerUserId, LocalDate.Value, now));
        if (feedback.ReportedDiscomfort)
        {
            Raise(new DiscomfortReported(Id, ClientId, TrainerUserId, now));
        }

        return Result.Success();
    }

    public Result ReplyToFeedback(Guid trainerProfileId, string message, DateTimeOffset now)
    {
        if (trainerProfileId != TrainerProfileId)
        {
            return WorkoutErrors.NotResponsibleTrainer;
        }

        if (Status != WorkoutStatus.Completed)
        {
            return WorkoutErrors.NotCompleted;
        }

        Reply = new FeedbackReply(message.Trim(), trainerProfileId, now);
        Raise(new FeedbackReplied(Id, ClientId, now));
        return Result.Success();
    }

    /// <summary>
    /// Records the Apple Health workout saved by the phone. The first id wins: a retry with the same id succeeds, a
    /// different id means a duplicate was saved and the phone must delete it.
    /// </summary>
    public Result RecordAppleHealthWorkout(Guid healthKitWorkoutId, DateTimeOffset savedAt, DateTimeOffset now)
    {
        if (Status != WorkoutStatus.Completed)
        {
            return WorkoutErrors.NotCompleted;
        }

        if (AppleHealthWorkout is { } existing)
        {
            return existing.ExternalWorkoutId == healthKitWorkoutId ? Result.Success() : WorkoutErrors.AlreadySavedToAppleHealth;
        }

        AppleHealthWorkout = new ExternalWorkoutExport(healthKitWorkoutId, savedAt, now);
        return Result.Success();
    }

    /// <summary>Time spent exercising, excluding pauses. Null while the session is open.</summary>
    public TimeSpan? ActiveDuration()
    {
        if (EndedAt is not { } end)
        {
            return null;
        }

        var paused = _pauses.Aggregate(TimeSpan.Zero, (total, p) => total + ((p.ResumedAt ?? end) - p.PausedAt));
        return end - StartedAt - paused;
    }

    private void CloseOpenPause(DateTimeOffset at)
    {
        var open = _pauses.LastOrDefault(p => p.ResumedAt is null);
        open?.Close(at < open.PausedAt ? open.PausedAt : at);
    }
}

public sealed record WorkoutCompleted(Guid WorkoutSessionId, Guid ClientId, Guid TrainerUserId, DateOnly LocalDate, DateTimeOffset OccurredAt)
    : DomainEvent(OccurredAt);

public sealed record DiscomfortReported(Guid WorkoutSessionId, Guid ClientId, Guid TrainerUserId, DateTimeOffset OccurredAt)
    : DomainEvent(OccurredAt);

public sealed record FeedbackReplied(Guid WorkoutSessionId, Guid ClientId, DateTimeOffset OccurredAt) : DomainEvent(OccurredAt);
